module {
  func.func @main(%arg0: tensor<6x1x1xf32>,    // multiplier
                 %arg1: tensor<6x6x3x3xf32>,  // conv.weight
                 %arg2: tensor<6xf32>,        // conv.bias (not used in this implementation)
                 %arg3: tensor<6x6x7x7xf32>) -> tensor<6x6x5x5xf32> {
    // Step 1: Perform convolution
    %conv_padding = dense<[[1, 1], [1, 1]]> : tensor<2x2xi64>
    %conv_strides = dense<1, 1> : tensor<2xi64>
    %lhs_dilation = dense<1, 1> : tensor<2xi64>
    %rhs_dilation = dense<1, 1> : tensor<2xi64>
