      batch_group_count = 1 : i64
    } : (tensor<6x6x7x7xf32>, tensor<6x6x3x3xf32>) -> tensor<6x6x5x5xf32>

    // Step 2: Multiply by multiplier
    // Broadcast multiplier to match conv_result shape
    // conv_result shape: [6,6,5,5]
    // multiplier shape: [6]
    // Broadcast along dims 1,2,3
    %multiplier_broadcast = "stablehlo.broadcast_in_dim"(%arg0) {
      broadcast_dimensions = dense<0> : tensor<1xi64>
    } : (tensor<6x1x1xf32>) -> tensor<6x1x1xf32>
    // Expand to shape [6,6,5,5]
    %multiplier_expanded = "stablehlo.broadcast_in_dim"(%multiplier_broadcast) {
      broadcast_dimensions = dense<0, 1, 2> : tensor<3xi64>
    } : (tensor<6x1x1xf32>) -> tensor<6x6x5x5xf32>
    // Now multiply element-wise
    %mul = "stablehlo.multiply"(%conv_result, %multiplier_expanded) : (tensor<6x6x5x5xf32>, tensor<6x6x5x5xf32>) -> tensor<6x6x5x5xf32>

    // Step 3: Apply LeakyReLU
    // LeakyReLU: max(x, 0) + negative_slope * min(x, 0)
    // For simplicity, assume negative_slope = 0.01
    %zero = "stablehlo.constant"() {value = dense<0.0> : tensor<f32>} : () -> tensor<f32>
    // max(x, 0)
    %x_max_zero = "stablehlo.maximum"(%mul, %zero) : (tensor<6x6x5x5xf32>, tensor<f32>) -> tensor<6x6x5x5xf32>
    // min(x, 0)
    %x_min_zero = "stablehlo.minimum"(%mul, %zero) : (tensor<6x6x5x5xf32>, tensor<f32>) -> tensor<6x6x5x5xf32>
    // negative_slope * min(x, 0)
    %neg_slope = "stablehlo.constant"() {value = dense<0.01> : tensor<f32>} : () -> tensor<f32>
    %scaled_min = "stablehlo.multiply"(%neg_slope, %x_min_zero) : (tensor<f32>, tensor<6x6x5x5xf32>) -> tensor<6x6x5x5xf32>
    // LeakyReLU output
    %leaky_relu = "stablehlo.add"(%x_max_zero, %scaled_min) : (tensor<6x6x5x5xf32>, tensor<6x6x5x5xf32>) -> tensor<6x6x5x5xf32>

    // Step 4: Apply GELU
    // GELU approximation: 0.5 * x * (1 + tanh(√(2/π) * (x + 0.044715 * x^3)))
    // Constants
    %one_half = "stablehlo.constant"() {value = dense<0.5> : tensor<f32>} : () -> tensor<f32>
    %sqrt_2_over_pi = "stablehlo.constant"() {value = dense<0.7978845608> : tensor<f32>} : () -> tensor<f32>
    %coeff = "stablehlo.constant"() {value = dense<0.044715> : tensor<f32>} : () -> tensor<f32>
    // x^3
    %x_cubed = "stablehlo.multiply"(%leaky_relu, %leaky_relu) : (tensor<f32>, tensor<f32>) -> tensor<f32>
    %x_cubed2 = "stablehlo.multiply"(%x_cubed, %leaky_relu) : (tensor<f32>, tensor<f32>) -> tensor<f32>
    // x + 0.044715 * x^3
    %x_times_coeff = "stablehlo.multiply"(%coeff, %x_cubed) : (tensor<f32>, tensor<f32>) -> tensor<f32>
    %x_plus = "stablehlo.add"(%leaky_relu, %x_times_coeff) : (tensor<f32>, tensor<f32>) -> tensor<f32>
    // Compute tanh argument
    %tanh_arg = "stablehlo.multiply"(%sqrt_2_over_pi, %x_plus) : (tensor<f32>, tensor<f32>) -> tensor<f32>
    // Approximate tanh using built-in or MLIR operations
    // Since no tanh op is specified, approximate tanh as (exp(x) - exp(-x)) / (exp(x) + exp(-x))
    %exp_x = "stablehlo.exponential"(%tanh_arg) : (tensor<f32>) -> tensor<f32>
    %neg_exp_x = "stablehlo.exponential"("stablehlo.negate"(%tanh_arg) : tensor<f32>) : (tensor<f32>) -> tensor<f32>
    // numerator: exp(x) - exp(-x)
    %num = "stablehlo.subtract"(%exp_x, %neg_exp_x) : (tensor<f32>, tensor<f32>) -> tensor<f32>
    // denominator: exp(x) + exp(-x)
    %den = "stablehlo.add"(%exp_x, %neg_exp_x) : (tensor<f32>, tensor<f32>) -> tensor<f32>
    // tanh approximation
    %tanh = "stablehlo.divide"(%num, %den) : (tensor<f32>, tensor<f32>) -> tensor<f32>
    // 1 + tanh
    %one = "stablehlo.constant"() {value = dense<1.0> : tensor<f32>} : () -> tensor<f32>
    %tanh_plus_one = "stablehlo.add"(%one, %tanh) : (tensor<f32>, tensor<f32>) -> tensor<f32>
    // Final GELU: 0.5 * x * (1 + tanh(...))
    %gelu_intermediate = "stablehlo.multiply"(%leaky_relu, %tanh_plus_one) : (tensor<f32>, tensor<f32>) -> tensor<f32>
    %gelu = "stablehlo.multiply"(%one_half, %gelu_intermediate) : (tensor<f32>, tensor<f32>) -> tensor<f32>

    // Output shape: [6,6,5,5]
    return %gelu : tensor<6x6x5x5xf32>
  }
}

