  %one_plus_erf = "stablehlo.add"(%one, %erf_x) : (tensor<f32>, tensor<f32>) -> tensor<f32>
  // 0.5 * x
  %half = "stablehlo.constant"() {value = dense<0.5> : tensor<f32>} : () -> tensor<f32>
  %x_times_half = "stablehlo.multiply"(%features, %half) : (tensor<16xf32>, tensor<f32>) -> tensor<16xf32>
  // GELU output: 0.5 * x * (1 + erf(x / sqrt(2)))
  %gelu = "stablehlo.multiply"(%x_times_half, %one_plus_erf) : (tensor<16xf32>, tensor<f32>) -> tensor<16xf32>

  // Step 4: Scale by scale_factor (which is 2.0)
  %scale_factor = "stablehlo.constant"() {value = dense<2.0> : tensor<f32>} : () -> tensor<f32>
  %scaled = "stablehlo.multiply"(%gelu, %scale_factor) : (tensor<16xf32>, tensor<f32>) -> tensor<16xf32>

