  // For max reduction, initialize with -inf
  %minus_inf = "stablehlo.constant"() {value = dense<0xFF800000> : tensor<f32>} : () -> tensor<f32>
  // Reduce over dimension 1
  %max_result = "stablehlo.reduce"(%scaled, %minus_inf) {
    axes = dense<[1]> : tensor<1xi64>
  } : (tensor<16x16xf32>, tensor<f32>) -> tensor<16xf32>

  // Return the result
  "stablehlo.return"(%max_result) : (tensor<16xf32>) -> ()
}

