// Entry function signature:
// func.func @main(%arg0: tensor<16x16x16x16xf32>) -> tensor<16x16x1x1xf32>

func.func @main(%arg0: tensor<16x16x16x16xf32>) -> tensor<16x16x1x1xf32> {
  // Step 1: Define constants for kernel size, stride, and padding
  %kernel_size = "stablehlo.constant"() {value = dense<11> : tensor<i64>} : () -> tensor<i64>
  %stride = "stablehlo.constant"() {value = dense<11> : tensor<i64>} : () -> tensor<i64>
  %padding = "stablehlo.constant"() {value = dense<0> : tensor<i64>} : () -> tensor<i64>

  // Step 2: Compute padding for each spatial dimension
  // Since padding is 0, we can set padding for height and width to zero
  // Create padding array: shape [rank(input), 2]
  // For input shape: [16,16,16,16], spatial dims are dims 2 and 3
  // Padding for batch and channels is zero
  %padding_array = "stablehlo.constant"() {value = dense<[[0,0], [0,0], [0,0], [0,0]]]> : tensor<4x2xi64>} : () -> tensor<4x2xi64>

