  // For each spatial dimension (height and width), compute output size
  // Using the formula:
  // out_dim = floor((lo + (n-1)*base_dilation + 1 + hi - ((w-1)*window_dilation + 1)) / stride) + 1
  // Since base_dilation and window_dilation are 1, and padding is 0:
  // out_dim = floor((0 + (16-1)*1 + 1 + 0 - ((11-1)*1 + 1)) / 11) + 1
  // Simplify:
  // out_dim = floor((15 + 1 - (10 + 1)) / 11) + 1 = floor((16 - 11) / 11) + 1 = floor(5/11) + 1 = 0 + 1 = 1

  // Step 4: Perform reduce_window with average pooling
  // The window shape is [11,11], strides [11,11], padding as computed
  // Initialize the accumulator with zeros
  %init = "stablehlo.constant"() {value = dense<0.0> : tensor<f32>} : () -> tensor<f32>

  // Step 5: Define the reduction body: sum over the window
  ^bb0(%a: tensor<f32>, %b: tensor<f32>):
    %sum = "stablehlo.add" %a, %b : tensor<f32>
    "stablehlo.return" %sum : tensor<f32>

  // Step 6: Apply reduce_window to compute sum over each window
  %sum_result = "stablehlo.reduce_window"(%arg0, %init)
    ({ ^bb0(%a: tensor<f32>, %b: tensor<f32>):
        %sum = "stablehlo.add" %a, %b : tensor<f32>
        "stablehlo.return" %sum : tensor<f32> })
    {window_dimensions = array<i64: 11, 11>,
     window_strides = array<i64: 11, 11>,
     padding = dense<[[0,0], [0,0], [0,0], [0,0]]]>} : (tensor<16x16x16x16xf32>, tensor<f32>) -> tensor<16x16x16x16xf32>

  // Step 7: Compute the average by dividing sum by the number of elements in the window (11*11=121)
  %window_size = "stablehlo.constant"() {value = dense<121.0> : tensor<f32>} : () -> tensor<f32>
  %avg = "stablehlo.divide" %sum_result, %window_size : tensor<16x16x1x1xf32>, tensor<f32> -> tensor<16x16x1x1xf32>

  // Step 8: Return the averaged tensor
  "stablehlo.return" %avg : tensor<16x16x1x1xf32>
