    { broadcast_dimensions = array<i64: 0> }
    : (tensor<6x1x1x1>) -> tensor<6x6x15x15xf32>
  // Add bias
  %add_bias = "stablehlo.add"(%softmax, %bias_bcast)
    : (tensor<6x6x15x15xf32>, tensor<6x6x15x15xf32>) -> tensor<6x6x15x15xf32>

  // Step 4: Scale by 2.0
