    : (tensor<6x6x15x15xf32>, tensor<f32>) -> tensor<6x6x15x15xf32>

  // Step 5: Apply sigmoid
  // sigmoid(x) = 1 / (1 + exp(-x))
  %neg_x = "stablehlo.negate"(%scaled) : (tensor<6x6x15x15xf32>) -> tensor<6x6x15x15xf32>
  %exp_neg_x = "stablehlo.exponential"(%neg_x) : (tensor<6x6x15x15xf32>) -> tensor<6x6x15x15xf32>
  %one = "stablehlo.constant"() { value = dense<1.0> : tensor<f32> }
    : () -> tensor<f32>
  %denominator = "stablehlo.add"(%one, %exp_neg_x)
    : (tensor<f32>, tensor<6x6x15x15xf32>) -> tensor<6x6x15x15xf32>
  %sigmoid = "stablehlo.divide"(%one, %denominator)
    : (tensor<f32>, tensor<6x6x15x15xf32>) -> tensor<6x6x15x15xf32>

  // Return the final output
  return %sigmoid : tensor<6x6x15x15xf32>
}

