      ^bb0(%a: tensor<6x7xf32>, %b: tensor<6x7xf32>) {
        %s = "stablehlo.add"(%a, %b) : (tensor<6x7xf32>, tensor<6x7xf32>) -> tensor<6x7xf32>
        "stablehlo.return"(%s) : (tensor<6x7xf32>) -> ()
      }
    } : (tensor<6x7xf32>, tensor<6x7xf32>) -> tensor<6x7xf32>
    // Compute mean: divide sum by batch size (6)
