    // Compute variance: sum of squared differences
    // diff = x_scaled - mean_x
    %diff = "stablehlo.subtract"(%x_scaled, %mean_x_scaled) : (tensor<6x7xf32>, tensor<6x7xf32>) -> tensor<6x7xf32>
    // square diff
    %diff_sq = "stablehlo.multiply"(%diff, %diff) : (tensor<6x7xf32>, tensor<6x7xf32>) -> tensor<6x7xf32>
    // sum squared diff over batch
    %sum_sq = "stablehlo.reduce"(%diff_sq, %zero) {
      ^bb0(%a: tensor<6x7xf32>, %b: tensor<6x7xf32>) {
        %s = "stablehlo.add"(%a, %b) : (tensor<6x7xf32>, tensor<6x7xf32>) -> tensor<6x7xf32>
        "stablehlo.return"(%s) : (tensor<6x7xf32>) -> ()
      }
    } : (tensor<6x7xf32>, tensor<6x7xf32>) -> tensor<6x7xf32>
    // variance = sum_sq / (batch_size - 1)
    %batch_minus_one = "stablehlo.subtract"(%batch_size_const, %one_dim) : (tensor<i64>, tensor<i64>) -> tensor<i64>
    %batch_minus_one_f32 = "stablehlo.convert"(%batch_minus_one) {to = tensor<f32>}
    %var_bcast = "stablehlo.exponential"(%batch_minus_one_f32) : (tensor<f32>) -> tensor<f32> // placeholder for reciprocal
