    %variance = "stablehlo.multiply"(%sum_sq, %inv_bsize_minus_one) : (tensor<6x7xf32>, tensor<f32>) -> tensor<6x7xf32>

    // Normalize: (x_scaled - mean) / sqrt(variance + epsilon)
    %epsilon = constant dense<1e-5> : tensor<f32>
    %var_plus_epsilon = "stablehlo.add"(%variance, %epsilon) : (tensor<6x7xf32>, tensor<f32>) -> tensor<6x7xf32>
    // sqrt of variance + epsilon
    %stddev = "stablehlo.sqrt"(%var_plus_epsilon) : (tensor<6x7xf32>) -> tensor<6x7xf32>
    // Normalize
    %x_centered = "stablehlo.subtract"(%x_scaled, %mean_x_scaled) : (tensor<6x7xf32>, tensor<6x7xf32>) -> tensor<6x7xf32>
    %x_norm = "stablehlo.divide"(%x_centered, %stddev) : (tensor<6x7xf32>, tensor<6x7xf32>) -> tensor<6x7xf32>

