      broadcast_dimensions = array<i64: 0>
    } : (tensor<7xf32>) -> tensor<6x7xf32>
    // Element-wise multiply
    %x_scaled_bn = "stablehlo.multiply"(%x_norm, %bn_weight_bcast) : (tensor<6x7xf32>, tensor<6x7xf32>) -> tensor<6x7xf32>
    // Add bias
    %bn_output = "stablehlo.add"(%x_scaled_bn, %bn_bias_bcast) : (tensor<6x7xf32>, tensor<6x7xf32>) -> tensor<6x7xf32>

    // Return bn_output
    "stablehlo.return"(%bn_output) : (tensor<6x7xf32>) -> ()
  }
}

// StableHLO program implementing the forward pass of the described PyTorch model
// with parameters passed as arguments, following the specified signature.

func.func @main(%arg0: tensor<16xf32>,        // multiply_weight
               %arg1: tensor<16x16xf32>,     // gemm.weight
               %arg2: tensor<16xf32>,        // gemm.bias
               %arg3: tensor<16xf32>,        // group_norm.weight
               %arg4: tensor<16xf32>,        // group_norm.bias
               %arg5: tensor<16x16xf32>) -> tensor<16x16xf32> {
  // Step 1: GEMM (linear layer)
  // For GEMM: output = input * weight^T + bias
  // input: %arg5
  // weight: %arg1
  // bias: %arg2

  // Transpose weight for matmul
  %weight_T = "stablehlo.transpose"(%arg1) {permutation = array<i64: 1, 0>} : (tensor<16x16xf32>) -> tensor<16x16xf32>

  // Dot general: input * weight^T
