  %gn_output = "stablehlo.add"(%gn_scaled, %gn_bias_bcast) : (tensor<16x16xf32>, tensor<16x16xf32>) -> tensor<16x16xf32>

  // Step 3: Swish activation: x * sigmoid(x)
  %zero = "stablehlo.constant"() {value = dense<0.0> : tensor<f32>} : () -> tensor<f32>
  // sigmoid(x) = 1 / (1 + exp(-x))
  %neg_x = "stablehlo.negate"(%gn_output) : (tensor<16x16xf32>) -> tensor<16x16xf32>
  %exp_neg_x = "stablehlo.exponential"(%neg_x) : (tensor<16x16xf32>) -> tensor<16x16xf32>
  %one = "stablehlo.constant"() {value = dense<1.0> : tensor<f32>} : () -> tensor<f32>
  %denominator = "stablehlo.add"(%one, %exp_neg_x) : (tensor<f32>, tensor<16x16xf32>) -> tensor<16x16xf32>
  %sigmoid_x = "stablehlo.divide"(%one, %denominator) : (tensor<f32>, tensor<16x16xf32>) -> tensor<16x16xf32>
  // Swish: x * sigmoid(x)
  %swish1 = "stablehlo.multiply"(%gn_output, %sigmoid_x) : (tensor<16x16xf32>, tensor<16x16xf32>) -> tensor<16x16xf32>

  // Step 4: Multiply by parameter (pass as argument)
  // broadcast multiply_weight
  %multiply_weight_bcast = "stablehlo.broadcast_in_dim"(%arg0) {
    broadcast_dimensions = array<i64: 0>
  } : (tensor<16xf32>) -> tensor<16x16xf32>
  %x1 = "stablehlo.multiply"(%swish1, %multiply_weight_bcast) : (tensor<16x16xf32>, tensor<16x16xf32>) -> tensor<16x16xf32>

  // Step 5: Swish again
  // sigmoid(x) again
  %neg_x2 = "stablehlo.negate"(%x1) : (tensor<16x16xf32>) -> tensor<16x16xf32>
  %exp_neg_x2 = "stablehlo.exponential"(%neg_x2) : (tensor<16x16xf32>) -> tensor<16x16xf32>
  %denominator2 = "stablehlo.add"(%one, %exp_neg_x2) : (tensor<f32>, tensor<16x16xf32>) -> tensor<16x16xf32>
  %sigmoid_x2 = "stablehlo.divide"(%one, %denominator2) : (tensor<f32>, tensor<16x16xf32>) -> tensor<16x16xf32>
  %final_output = "stablehlo.multiply"(%x1, %sigmoid_x2) : (tensor<16x16xf32>, tensor<16x16xf32>) -> tensor<16x16xf32>

  // Return the final tensor
  "stablehlo.return"(%final_output) : (tensor<16x16xf32>) -> ()
}

