module {
  func.func @main(%arg0: tensor<7x7xf32>, %arg1: tensor<7xf32>, %arg2: tensor<6x7xf32>) -> tensor<6x1xf32> {
    // Step 1: Compute linear(x) = matmul(%arg2, %arg0^T) + %arg1
    // Transpose %arg0 to get shape (7x7) -> (7x7), but since %arg0 is (7x7), transpose is optional
    // Actually, for matmul, we need to align dimensions:
    // linear weight: (7x7), input: (6x7), so matmul: (6x7) x (7x7)^T? No, the input is (6x7), weight is (7x7)
    // To do: matmul(%arg2, %arg0^T): %arg2: (6x7), %arg0: (7x7)
    // So, transpose %arg0 to (7x7) -> (7x7), but to match matmul, we need to do matmul(%arg2, %arg0^T)
    // Actually, since %arg0 is (7x7), and input is (6x7), to multiply with weight, we do:
    // output = matmul(%arg2, transpose(%arg0))
    // But in StableHLO, matmul is dot_general with appropriate dimension numbers.

    // Step 1a: Transpose %arg0
    %transposed_weight = "stablehlo.transpose"(%arg0) {permutation = array<i64: 1, 0>} : (tensor<7x7xf32>) -> tensor<7x7xf32>

    // Step 1b: Perform dot_general: %linear = matmul(%arg2, %transposed_weight)
    // Batch dims: none, contracting dims: last of %arg2 (dim 1), first of weight (dim 0)
    %linear = "stablehlo.dot_general"(%arg2, %transposed_weight) {
      dot_dimension_numbers = #stablehlo.dot<lhs_batching_dimensions = [], rhs_batching_dimensions = [], lhs_contracting_dimensions = [1], rhs_contracting_dimensions = [0]>
    } : (tensor<6x7xf32>, tensor<7x7xf32>) -> tensor<6x7xf32>

    // Step 2: Add bias (%arg1) to linear output
    // %arg1 shape: (7)
    // Broadcast bias to shape (6x7)
    %bias_broadcast = "stablehlo.broadcast_in_dim"(%arg1) {
      broadcast_dimensions = array<i64: 1>
    } : (tensor<7xf32>) -> tensor<6x7xf32>
    %linear_bias = "stablehlo.add"(%linear, %bias_broadcast) : (tensor<6x7xf32>, tensor<6x7xf32>) -> tensor<6x7xf32>

    // Step 3: Apply sigmoid activation
    %sigmoid = "stablehlo.exponential"(%linear_bias) : (tensor<6x7xf32>) -> tensor<6x7xf32>
    // Sigmoid = 1 / (1 + exp(-x))
    // Compute -x
    %neg_linear = "stablehlo.negate"(%linear_bias) : (tensor<6x7xf32>) -> tensor<6x7xf32>
    %exp_neg = "stablehlo.exponential"(%neg_linear) : (tensor<6x7xf32>) -> tensor<6x7xf32>
    // 1 + exp(-x)
    %one_const = "stablehlo.constant"() {value = dense<1.0> : tensor<f32>} : () -> tensor<f32>
    %denominator = "stablehlo.add"(%one_const, %exp_neg) : (tensor<f32>, tensor<f32>) -> tensor<f32>
    // Broadcast denominator to shape (6x7)
    %denominator_bcast = "stablehlo.broadcast_in_dim"(%denominator) {
      broadcast_dimensions = array<i64: 0>
    } : (tensor<f32>) -> tensor<6x7xf32>
    // Compute sigmoid
    %sigmoid_value = "stablehlo.divide"(%one_const, %denominator_bcast) : (tensor<f32>, tensor<6x7xf32>) -> tensor<6x7xf32>

    // Step 4: Sum over dim=1 (columns), keepdim=True -> result shape (6x1)
    // Reduce sum over dimension 1
    %init_zero = "stablehlo.constant"() {value = dense<0.0> : tensor<f32>} : () -> tensor<f32>
    %sum = "stablehlo.reduce"(%sigmoid_value, %init_zero) {
      axes = array<i64: 1>
    } : (tensor<6x7xf32>, tensor<f32>) -> tensor<6x1xf32>

    // Return the result
    return %sum : tensor<6x1xf32>
  }
}

