module {
  func.func @main(%arg0: tensor<7x8x3x3xf32>, %arg1: tensor<7xf32>, %arg2: tensor<6x8x6x6xf32>) -> tensor<6x7x4x4xf32> {
    // Step 1: Convolution
    %conv_padding = dense<[[1,1],[1,1]]> : tensor<2x2xi64>
    %conv_window_strides = dense< [1,1] > : tensor<2xi64>
    %conv_lhs_dilation = dense< [1,1] > : tensor<2xi64>
    %conv_rhs_dilation = dense< [1,1] > : tensor<2xi64>
    %dimension_numbers = #stablehlo.conv<[b, f, 0, 1]x[o, i, 0, 1]->[b, f, 0, 1]>
    %feature_group_count = 1 : i64
    %batch_group_count = 1 : i64

    %conv_result = "stablehlo.convolution"(%arg2, %arg0) {
      window_strides = %conv_window_strides,
      padding = %conv_padding,
      lhs_dilation = %conv_lhs_dilation,
      rhs_dilation = %conv_rhs_dilation,
      dimension_numbers = #stablehlo.conv<[b, f, 0, 1]x[o, i, 0, 1]>,
      feature_group_count = %feature_group_count : i64,
      batch_group_count = %batch_group_count : i64
    } : (tensor<6x8x6x6xf32>, tensor<7x8x3x3xf32>) -> tensor<6x7x4x4xf32>

    // Step 2: HardSwish activation
    // hardSwish(x) = x * relu6(x + 3) / 6
    // Implement relu6 as min(max(x + 3, 0), 6)

    // Compute x + 3
    %const_three = "stablehlo.constant"() {value = dense<3.0> : tensor<f32>} : () -> tensor<f32>
    %conv_result_bcast = "stablehlo.broadcast_in_dim"(%conv_result) {
      broadcast_dimensions = array<i64: 2>
    } : (tensor<6x7x4x4xf32>) -> tensor<6x7x4x4xf32>
    // Since broadcasting is not needed here (same shape), we can reuse the same tensor
    // but to be explicit, we broadcast the scalar
    %x_plus_3 = "stablehlo.add"(%conv_result, %const_three) : (tensor<6x7x4x4xf32>, tensor<f32>) -> tensor<6x7x4x4xf32>

    // Compute relu6(x + 3) = min(max(x + 3, 0), 6)
    %zero = "stablehlo.constant"() {value = dense<0.0> : tensor<f32>} : () -> tensor<f32>
    %six = "stablehlo.constant"() {value = dense<6.0> : tensor<f32>} : () -> tensor<f32>

    %relu6_max = "stablehlo.maximum"(%x_plus_3, %zero) : (tensor<6x7x4x4xf32>, tensor<f32>) -> tensor<6x7x4x4xf32>
    %relu6 = "stablehlo.minimum"(%relu6_max, %six) : (tensor<6x7x4x4xf32>, tensor<f32>) -> tensor<6x7x4x4xf32>

    // Compute hardSwish: x * relu6(x + 3) / 6
    %mul_x_relu6 = "stablehlo.multiply"(%conv_result, %relu6) : (tensor<6x7x4x4xf32>, tensor<6x7x4x4xf32>) -> tensor<6x7x4x4xf32>
    %inv_six = "stablehlo.constant"() {value = dense<0.16666667> : tensor<f32>} : () -> tensor<f32> // 1/6
    %hard_swish = "stablehlo.multiply"(%mul_x_relu6, %inv_six) : (tensor<6x7x4x4xf32>, tensor<f32>) -> tensor<6x7x4x4xf32>

    // Step 3: ReLU activation
    %zero_relu = "stablehlo.constant"() {value = dense<0.0> : tensor<f32>} : () -> tensor<f32>
    %output = "stablehlo.maximum"(%hard_swish, %zero_relu) : (tensor<6x7x4x4xf32>, tensor<f32>) -> tensor<6x7x4x4xf32>

    // Return the final tensor
    return %output : tensor<6x7x4x4xf32>
  }
}

