// StableHLO program to compute pairwise squared Euclidean distances between rows of x and y
func.func @main(%x: tensor<4x5xf32>, %y: tensor<2x5xf32>) -> tensor<4x2xf32> {
  // Step 1: Broadcast %x to shape [4, 5, 2]
  %x_bcast = "stablehlo.broadcast_in_dim"(%x) {
    broadcast_dimensions = array<i64: 0, 1, 1>
  } : (tensor<4x5xf32>) -> tensor<4x5x2xf32>

  // Step 2: Broadcast %y to shape [4, 5, 2]
  %y_bcast = "stablehlo.broadcast_in_dim"(%y) {
    broadcast_dimensions = array<i64: 2, 1, 0>
  } : (tensor<2x5xf32>) -> tensor<4x5x2xf32>

  // Step 3: Compute difference: diff = x_bcast - y_bcast
  %diff = "stablehlo.subtract"(%x_bcast, %y_bcast) : tensor<4x5x2xf32>

  // Step 4: Square the differences: diff_squared = diff * diff
  %diff_squared = "stablehlo.multiply"(%diff, %diff) : tensor<4x5x2xf32>

  // Step 5: Sum over the last dimension (dimension 1) to get squared distances
  %init = "stablehlo.constant"() {value = dense<0.0> : tensor<f32>} : () -> tensor<f32>
  %squared_distances = "stablehlo.reduce"(%diff_squared, %init) {
    dimensions = array<i64: 1>
  } ({
    ^bb0(%a: tensor<f32>, %b: tensor<f32>):
      %sum = "stablehlo.add"(%a, %b) : (tensor<f32>, tensor<f32>) -> tensor<f32>
      "stablehlo.return"(%sum) : (tensor<f32>) -> ()
  }) : (tensor<4x5x2xf32>, tensor<f32>) -> tensor<4x2xf32>

  // Return the result
  return %squared_distances : tensor<4x2xf32>
}

