    %min_const = "stablehlo.constant"() {value = dense<-2.0> : tensor<f32>} : () -> tensor<f32>
    %max_const = "stablehlo.constant"() {value = dense<2.0> : tensor<f32>} : () -> tensor<f32>
    // Apply Hardtanh: clip between min and max
    %clipped_min = "stablehlo.maximum" %scaled, %min_const : tensor<6x7xf32>
    %clipped = "stablehlo.minimum" %clipped_min, %max_const : tensor<6x7xf32>

    // Step 5: GELU activation
    // GELU approximation: 0.5 * x * (1 + tanh(√(2/π) * (x + 0.044715 * x^3)))
    // Constants
    %sqrt_2_over_pi = "stablehlo.constant"() {value = dense<0.7978845608> : tensor<f32>} // sqrt(2/π)
    %coeff = "stablehlo.constant"() {value = dense<0.044715> : tensor<f32>}
    %one = "stablehlo.constant"() {value = dense<1.0> : tensor<f32>}
    %half = "stablehlo.constant"() {value = dense<0.5> : tensor<f32>}

    // Compute x^3
    %x_cubed = "stablehlo.multiply" %clipped, %clipped : tensor<6x7xf32> // x * x
    %x_cubed2 = "stablehlo.multiply" %x_cubed, %clipped : tensor<6x7xf32> // x^3

    // Compute inner term: √(2/π) * (x + 0.044715 * x^3)
    %inner_add = "stablehlo.add" %clipped, "stablehlo.multiply" %coeff, %x_cubed2 : tensor<6x7xf32>
    %inner = "stablehlo.multiply" %sqrt_2_over_pi, %inner_add : tensor<6x7xf32>

    // tanh of inner
    %tanh_inner = "chlo.erf"(%inner) : (tensor<6x7xf32>) -> tensor<6x7xf32>
    // Note: chlo.erf computes erf, but for tanh approximation, we need tanh.
    // Since no tanh op, approximate tanh as erf scaled: tanh(x) ≈ erf(1.4142 * x)
    // Alternatively, use erf scaled: tanh(x) ≈ erf( (2/π)^0.5 * x )
    // But for simplicity, approximate tanh as erf scaled:
    // Let's implement tanh as: tanh(x) ≈ erf(1.4142 * x)
    %scale_tanh = "stablehlo.constant"() {value = dense<1.414213562> : tensor<f32>}
    %tanh_arg = "stablehlo.multiply" %inner, %scale_tanh : tensor<6x7xf32>
    %tanh = "chlo.erf" %tanh_arg : (tensor<6x7xf32>) -> tensor<6x7xf32>

    // Compute 1 + tanh
    %one_plus_tanh = "stablehlo.add" %one, %tanh : tensor<6x7xf32>
    // Multiply by 0.5
    %gelu_scale = "stablehlo.multiply" %half, %one_plus_tanh : tensor<6x7xf32>
    // Final GELU output
    %gelu_output = "stablehlo.multiply" %clipped, %gelu_scale : tensor<6x7xf32>

    // Return the final tensor
    return %gelu_output : tensor<6x7xf32>
  }
}

