// StableHLO program to compute the mean squared error between two tensors
// with signature: func.func @main(%arg0: tensor<6x6xf32>, %arg1: tensor<6x6xf32>) -> tensor<f32>

func.func @main(%arg0: tensor<6x6xf32>, %arg1: tensor<6x6xf32>) -> tensor<f32> {
  // Compute difference: diff = %arg0 - %arg1
  %diff = "stablehlo.subtract" %arg0, %arg1 : tensor<6x6xf32>

  // Compute squared difference: sq_diff = diff * diff
  %sq_diff = "stablehlo.multiply" %diff, %diff : tensor<6x6xf32>

  // Initialize reduction with zero tensor of shape scalar (single float)
  %zero_const = "stablehlo.constant"() {value = dense<0.0> : tensor<f32>} : () -> tensor<f32>

  // Reduce (sum) all elements of sq_diff to a scalar
  %sum_sq_diff = "stablehlo.reduce" %sq_diff, %zero_const
    ({ ^bb0(%a: tensor<f32>, %b: tensor<f32>): tensor<f32> {
        %sum = "stablehlo.add" %a, %b : tensor<f32>
        "stablehlo.return" %sum : tensor<f32>
      }
    }) {dimensions = array<i64: 0, 1>} : (tensor<6x6xf32>, tensor<f32>) -> tensor<f32>

  // Compute mean: result = sum / total_elements (36)
  // Create constant 36.0
  %divisor = "stablehlo.constant"() {value = dense<36.0> : tensor<f32>} : () -> tensor<f32>

  // Divide sum by 36.0
  %mean = "stablehlo.divide" %sum_sq_diff, %divisor : tensor<f32>

  // Return the scalar result
  "stablehlo.return" %mean : tensor<f32>
}

