  %pred_targets = "stablehlo.multiply" %arg0, %arg1 : tensor<6x6xf32>, tensor<6xf32> -> tensor<6x6xf32>

  // Step 2: Create a tensor of ones with shape [6,6] for min operation
  %one_dense = "stablehlo.constant"() {value = dense<1.0> : tensor<f32>} : () -> tensor<f32>
  %ones = "stablehlo.broadcast_in_dim" %one_dense {broadcast_dimensions = array<i64: 0, 1>} : (tensor<f32>) -> tensor<6x6xf32>

  // Step 3: Compute 1 - predictions * targets
  %one_minus = "stablehlo.subtract" %ones, %pred_targets : tensor<6x6xf32>, tensor<6x6xf32> -> tensor<6x6xf32>

  // Step 4: Clamp the result at min=0 (ReLU-like)
  %zero_dense = "stablehlo.constant"() {value = dense<0.0> : tensor<f32>} : () -> tensor<f32>
  %clamped = "stablehlo.maximum" %zero_dense, %one_minus : tensor<f32>, tensor<f32> -> tensor<6x6xf32>

  // Step 5: Compute mean over all elements
  // First, reduce sum over all elements
  %init_sum = "stablehlo.constant"() {value = dense<0.0> : tensor<f32>} : () -> tensor<f32>
  %sum = "stablehlo.reduce" %clamped, %init_sum {dimensions = array<i64: 0, 1>} 
    ({ 
      ^bb0(%a: tensor<f32>, %b: tensor<f32>): tensor<f32> {
        %s = "stablehlo.add" %a, %b : tensor<f32>, tensor<f32> -> tensor<f32>
        "stablehlo.return" %s : tensor<f32>
      } 
    }) : tensor<6x6xf32>, tensor<f32> -> tensor<f32>

  // Step 6: Compute mean by dividing sum by total number of elements (36)
  %div_const = "stablehlo.constant"() {value = dense<36.0> : tensor<f32>} : () -> tensor<f32>
  %mean = "stablehlo.divide" %sum, %div_const : tensor<f32>, tensor<f32> -> tensor<f32>

  // Return the scalar result
  "stablehlo.convert" %mean : tensor<f32> -> tensor<f32>
}

