// StableHLO program implementing the forward pass of the described PyTorch model
// with specified input and output tensor shapes.

func.func @main(%arg0: tensor<7xf32>, %arg1: tensor<7x7xf32>, %arg2: tensor<7xf32>, %arg3: tensor<6x7xf32>) -> tensor<6x7xf32> {
  // %arg0: add_value (tensor<7xf32>)
  // %arg1: matmul.weight (tensor<7x7xf32>)
  // %arg2: matmul.bias (tensor<7xf32>)
  // %arg3: input tensor (tensor<6x7xf32>)

  // Step 1: matrix multiplication: x = matmul(%arg3, %arg1)
  // For matmul, set batching dims empty, contracting dims last of lhs and first of rhs
  %lhs_rank = "stablehlo.constant"() {value = dense<2> : tensor<i64>} : () -> tensor<2>
  %rhs_rank = "stablehlo.constant"() {value = dense<2> : tensor<i64>} : () -> tensor<2>
  // shape of %arg3: 6x7, shape of %arg1: 7x7
  // batch dims: none, contracting dims: last of lhs (dim 1), first of rhs (dim 0)
  %matmul_result = "stablehlo.dot_general"(%arg3, %arg1) {
    dot_dimension_numbers = #stablehlo.dot<lhs_batching_dimensions = [], rhs_batching_dimensions = [], lhs_contracting_dimensions = [1], rhs_contracting_dimensions = [0]>
  } : (tensor<6x7xf32>, tensor<7x7xf32>) -> tensor<6x7xf32>

  // Step 2: add bias: %matmul_result + %arg2
  // Broadcast bias to shape 6x7
  %bias_broadcast = "stablehlo.broadcast_in_dim"(%arg2) {
    broadcast_dimensions = array<i64: 0, 1>
  } : (tensor<7xf32>) -> tensor<6x7xf32>
  %add_bias = "stablehlo.add"(%matmul_result, %bias_broadcast) : (tensor<6x7xf32>, tensor<6x7xf32>) -> tensor<6x7xf32>

  // Step 3: apply sigmoid (swish): sigmoid(x) * x
  // sigmoid(x) = 1 / (1 + exp(-x))
  %neg_x = "stablehlo.negate"(%add_bias) : tensor<6x7xf32>
  %exp_neg_x = "stablehlo.exponential"(%neg_x) : tensor<6x7xf32>
  %one = "stablehlo.constant"() {value = dense<1.0> : tensor<f32>} : () -> tensor<f32>
  %denominator = "stablehlo.add"(%one, %exp_neg_x) : (tensor<f32>, tensor<f32>) -> tensor<f32>
  %sigmoid = "stablehlo.divide"(%one, %denominator) : (tensor<f32>, tensor<f32>) -> tensor<f32>
  // swish: sigmoid(x) * x
  %swish = "stablehlo.multiply"(%sigmoid, %add_bias) : (tensor<6x7xf32>, tensor<6x7xf32>) -> tensor<6x7xf32>

  // Step 4: tanh activation
  %tanh_x = "stablehlo.tanh"(%swish) : tensor<6x7xf32>

  // Step 5: GELU activation
  // GELU: approximate with torch.nn.functional.gelu
  // GELU ≈ 0.5 * x * (1 + tanh(√(2/π) * (x + 0.044715 * x^3)))
  // For simplicity, use the approximation:
  // gelu(x) = 0.5 * x * (1 + tanh(√(2/π) * (x + 0.044715 * x^3)))
  // Compute x^3
  %x_cubed = "stablehlo.power"(%tanh_x, %one_const) : (tensor<6x7xf32>, tensor<1>) -> tensor<6x7xf32>
  // But need to multiply x * x * x, so use multiply twice
  // Instead, do: x^3 = x * x * x
  // First, x^2
  %x_squared = "stablehlo.multiply"(%tanh_x, %tanh_x) : tensor<6x7xf32>
  // x^3
  %x_cubed2 = "stablehlo.multiply"(%x_squared, %tanh_x) : tensor<6x7xf32>
  // 0.044715 * x^3
  %const_0_044715 = "stablehlo.constant"() {value = dense<0.044715> : tensor<f32>} : () -> tensor<f32>
  %term1 = "stablehlo.multiply"(%const_0_044715, %x_cubed2) : tensor<f32>, tensor<6x7xf32> -> tensor<6x7xf32>
  // x + 0.044715 * x^3
  %x_plus = "stablehlo.add"(%tanh_x, %term1) : tensor<6x7xf32>
  // sqrt(2/π)
  %sqrt_2_over_pi = "stablehlo.constant"() {value = dense<0.7978845608> : tensor<f32>} : () -> tensor<f32>
  // multiply with sqrt(2/π)
  %inner = "stablehlo.multiply"(%sqrt_2_over_pi, %x_plus) : tensor<f32>, tensor<6x7xf32> -> tensor<6x7xf32>
  // tanh of inner
  %tanh_inner = "stablehlo.tanh"(%inner) : tensor<6x7xf32>
  // 1 + tanh(...)
  %one_plus = "stablehlo.add"(%one, %tanh_inner) : tensor<6x7xf32>
  // 0.5 * x * (1 + tanh(...))
  %half = "stablehlo.constant"() {value = dense<0.5> : tensor<f32>} : () -> tensor<f32>
  %x_times = "stablehlo.multiply"(%half, %tanh_x) : tensor<6x7xf32>, tensor<f32> -> tensor<6x7xf32>
  %gelu = "stablehlo.multiply"(%x_times, %one_plus) : tensor<6x7xf32>, tensor<6x7xf32> -> tensor<6x7xf32>

  // Step 6: Hardtanh activation with min -1, max 1
  // Hardtanh: clip between -1 and 1
  %minus_one = "stablehlo.constant"() {value = dense<-1.0> : tensor<f32>} : () -> tensor<f32>
  %one_clip = "stablehlo.constant"() {value = dense<1.0> : tensor<f32>} : () -> tensor<f32>
  %clipped1 = "stablehlo.maximum"(%gelu, %minus_one) : (tensor<6x7xf32>, tensor<f32>) -> tensor<6x7xf32>
  %clipped2 = "stablehlo.minimum"(%clipped1, %one_clip) : (tensor<6x7xf32>, tensor<f32>) -> tensor<6x7xf32>

  // Output is %clipped2
  return %clipped2 : tensor<6x7xf32>
}

