  %Q_K_dot = "stablehlo.dot_general"(%arg0, %K_T) {dot_dimension_numbers = %dot_dim_numbers} : (tensor<6x6x7x8xf32>, tensor<6x6x7x8xf32>) -> tensor<6x6x7x8xf32>

  // Step 2: Scale by 1/sqrt(8) ≈ 0.3535534
