  %scale_const = "stablehlo.constant"() {value = dense<0.3535534> : tensor<f32>} : () -> tensor<f32>
  // Broadcast scale to shape of Q_K_dot
  %scale_bcast = "stablehlo.broadcast_in_dim"(%scale_const) {broadcast_dimensions = array<i64: 0>} : (tensor<f32>) -> tensor<6x6x7x8xf32>
  // Element-wise multiply scaled
  %scaled_scores = "stablehlo.multiply"(%Q_K_dot, %scale_bcast) : (tensor<6x6x7x8xf32>, tensor<6x6x7x8xf32>) -> tensor<6x6x7x8xf32>

  // Step 3: Apply softmax over sequence dimension (dim=2)
  // For simplicity, approximate softmax as: exp(x) / sum(exp(x))
  // Compute exp
  %exp_scores = "stablehlo.exponential"(%scaled_scores) : tensor<6x6x7x8xf32>
  // Reduce sum over dim=2 (sequence length)
  %reduce_dims = array<i64: 2>
  %sum_exp = "stablehlo.reduce"(%exp_scores, %c0) {dimensions = %reduce_dims} : (tensor<6x6x7x8xf32>, tensor<f32>) -> tensor<6x6x8xf32>
  // Create broadcast for sum
  %sum_exp_bcast = "stablehlo.broadcast_in_dim"(%sum_exp) {broadcast_dimensions = array<i64: 2>} : (tensor<6x6x8xf32>) -> tensor<6x6x7x8xf32>
