  %attention_weights = "stablehlo.divide"(%exp_scores, %sum_exp_bcast) : (tensor<6x6x7x8xf32>, tensor<6x6x7x8xf32>) -> tensor<6x6x7x8xf32>

  // Step 4: Multiply attention weights with V
  %attn_V = "stablehlo.multiply"(%attention_weights, %arg2) : (tensor<6x6x7x8xf32>, tensor<6x6x7x8xf32>) -> tensor<6x6x7x8xf32>

  return %attn_V : tensor<6x6x7x8xf32>
