func.func @main(%arg0: tensor<12x12xf32>, %arg1: tensor<12x12xf32>) -> tensor<f32> {
  // Step 1: Compute log of predictions: log_pred = log(%arg0)
  %log_pred = "stablehlo.log"(%arg0) : tensor<12x12xf32>

  // Step 2: Compute kl_div = kl_div(log_pred, %arg1)
  // Using: torch.nn.functional.kl_div(input, target, reduction='batchmean')
  // In StableHLO, kl_div = sum over all elements of target * (log(target) - input)
  // But since the original uses torch.nn.functional.kl_div with log_input, we implement as:
  // kl_div = sum(target * (log(target) - log_pred))
  // To do that, compute log(target) first

  // Step 2a: Compute log(target)
  %log_target = "stablehlo.log"(%arg1) : tensor<12x12xf32>

  // Step 2b: Compute (log(target) - log_pred)
  %diff_log = "stablehlo.subtract"(%log_target, %log_pred) : tensor<12x12xf32>

  // Step 2c: Element-wise multiply target with diff_log
  %mul_target_diff = "stablehlo.multiply"(%arg1, %diff_log) : tensor<12x12xf32>

  // Step 2d: Sum all elements of the result
  // Use reduce with addition over all dims
  %init_zero = "stablehlo.constant"() {value = dense<0.0> } : () -> tensor<f32>
  %sum_all = "stablehlo.reduce"(%mul_target_diff, %init_zero) {
    ^bb0(%a: tensor<f32>, %b: tensor<f32>):
      %s = "stablehlo.add"(%a, %b) : tensor<f32>, tensor<f32> -> tensor<f32>
      "stablehlo.return"(%s) : (tensor<f32>) -> ()
  } : (tensor<12x12xf32>, tensor<f32>) -> tensor<f32> {dimensions = array<i64: 0, 1>}

  // The reduction sums over dims 0 and 1, resulting in a scalar
  // The reduction above sums over all dims, so sum_all is scalar

  // Step 3: Compute the number of elements for normalization (batchmean)
  // total elements = 12 * 12 = 144
  // But in the original, reduction='batchmean' divides sum by batch size
  // So, divide sum by 144.0
  %div_const = "stablehlo.constant"() {value = dense<144.0> } : () -> tensor<f32>
  %kl_value = "stablehlo.divide"(%sum_all, %div_const) : tensor<f32>, tensor<f32> -> tensor<f32>

  // Return the scalar as output
  return %kl_value : tensor<f32>
}

// StableHLO program implementing the forward pass of the described PyTorch model
// with specified inputs and output shape.

module {
  func.func @main(
    %arg0: tensor<f32>,                                // scale1
