// StableHLO program implementing the described model forward pass
module {
  func.func @main(%arg0: tensor<16x16xf32>, %arg1: tensor<16xf32>, %arg2: tensor<16xf32>, %arg3: tensor<16xf32>, %arg4: tensor<16x16xf32>) -> tensor<16x16xf32> {
    // Step 1: Compute fc = matmul(%arg4, %arg0^T)
    // Transpose %arg0 to get shape (16,16)
    %arg0_T = "stablehlo.transpose"(%arg0) {permutation = array<i64: 1, 0>} : (tensor<16x16xf32>) -> tensor<16x16xf32>
    // Dot general: %fc = matmul(%arg4, %arg0^T)
    %fc = "stablehlo.dot_general"(%arg4, %arg0_T) {
      dot_dimension_numbers = #stablehlo.dot<lhs_batching_dimensions = [], rhs_batching_dimensions = [], lhs_contracting_dimensions = [1], rhs_contracting_dimensions = [0]>
    } : (tensor<16x16xf32>, tensor<16x16xf32>) -> tensor<16x16xf32>

    // Step 2: Broadcast %arg2 (gn.weight) to shape (16,16)
    // Already shape (16), broadcast to (16,16)
    %gn_weight_bcast = "stablehlo.broadcast_in_dim"(%arg2) {
      broadcast_dimensions = array<i64: 1>
    } : (tensor<16xf32>) -> tensor<16x16xf32>

    // Step 3: Broadcast %arg3 (gn.bias) to shape (16)
    // For addition, keep shape (16)
    // (No broadcast needed for bias in element-wise addition with %fc, but for clarity, keep as tensor<16>)
    // Step 4: GroupNorm: normalize %fc with weight and bias
    // Compute mean and variance over last dimension (dim=1)
    // For simplicity, approximate normalization: (x - mean) / sqrt(variance + epsilon)
    // Compute mean over last dimension
    // Reduce sum over dim=1
    %sum_fc = "stablehlo.reduce"(%fc, %zero = "stablehlo.constant"() {value = dense<0.0> : tensor<f32>}) {
      dimensions = array<i64: 1>
    } : (tensor<16x16xf32>, tensor<f32>) -> tensor<16x16xf32>
    // Compute mean: sum / 16
    %dim16 = "stablehlo.constant"() {value = dense<16> : tensor<i64>}
    %gn_mean = "stablehlo.convert"(%sum_fc) // placeholder for division
    %gn_mean_div = "stablehlo.divide"(%sum_fc, %dim16) : (tensor<16x16xf32>, tensor<i64>) -> tensor<16x16xf32>
    // For variance, compute squared difference
    %diff = "stablehlo.subtract"(%fc, "stablehlo.broadcast_in_dim"(%gn_mean_div) {broadcast_dimensions = array<i64: 1>}) : (tensor<16x16xf32>, tensor<16x16xf32>) -> tensor<16x16xf32>
    %diff_sq = "stablehlo.multiply"(%diff, %diff) : (tensor<16x16xf32>, tensor<16x16xf32>) -> tensor<16x16xf32>
    %sum_diff_sq = "stablehlo.reduce"(%diff_sq, %zero) {
      dimensions = array<i64: 1>
    } : (tensor<16x16xf32>, tensor<f32>) -> tensor<16x16xf32>
    %gn_var = "stablehlo.divide"(%sum_diff_sq, %dim16) : (tensor<16x16xf32>, tensor<i64>) -> tensor<16x16xf32>
    // Compute stddev = sqrt(variance + epsilon)
    %epsilon = "stablehlo.constant"() {value = dense<1e-5 : f32>}
    %var_plus_eps = "stablehlo.add"(%gn_var, "stablehlo.broadcast_in_dim"(%epsilon) {broadcast_dimensions = array<i64: 1>}) : (tensor<16x16xf32>, tensor<f32>) -> tensor<16x16xf32>
    %gn_stddev = "stablehlo.sqrt"(%var_plus_eps) : (tensor<16x16xf32>) -> tensor<16x16xf32>
    // Normalize: (x - mean) / stddev
    %x_centered = "stablehlo.subtract"(%fc, "stablehlo.broadcast_in_dim"(%gn_mean_div) {broadcast_dimensions = array<i64: 1>}) : (tensor<16x16xf32>, tensor<16x16xf32>) -> tensor<16x16xf32>
    %gn_norm = "stablehlo.divide"(%x_centered, "stablehlo.broadcast_in_dim"(%gn_stddev) {broadcast_dimensions = array<i64: 1>}) : (tensor<16x16xf32>, tensor<16x16xf32>) -> tensor<16x16xf32>
    // Scale and shift: gn_weight_bcast * gn_norm + gn_bias
    %scaled = "stablehlo.multiply"(%gn_weight_bcast, %gn_norm) : (tensor<16x16xf32>, tensor<16x16xf32>) -> tensor<16x16xf32>
    %gn_bias_bcast = "stablehlo.broadcast_in_dim"(%arg3) {broadcast_dimensions = array<i64: 1>} : (tensor<16xf32>) -> tensor<16x16xf32>
    %gn_scaled = "stablehlo.add"(%scaled, %gn_bias_bcast) : (tensor<16x16xf32>, tensor<16x16xf32>) -> tensor<16x16xf32>

    // Step 5: LeakyReLU activation
    // alpha = 0.01
    %alpha = "stablehlo.constant"() {value = dense<0.01 : f32>}
    // Compute max(%gn_scaled, 0)
    %zero_f32 = "stablehlo.constant"() {value = dense<0.0> : tensor<f32>}
    %leaky_relu_part = "stablehlo.maximum"(%gn_scaled, %zero_f32) : (tensor<16x16xf32>, tensor<f32>) -> tensor<16x16xf32>
    // Compute negative part: min(%gn_scaled, 0)
    %neg_part = "stablehlo.minimum"(%gn_scaled, %zero_f32) : (tensor<16x16xf32>, tensor<f32>) -> tensor<16x16xf32>
    // Multiply negative part by alpha
    %neg_scaled = "stablehlo.multiply"(%neg_part, %alpha) : (tensor<16x16xf32>, tensor<f32>) -> tensor<16x16xf32>
    // Add both parts
    %leaky_relu = "stablehlo.add"(%leaky_relu_part, %neg_scaled) : (tensor<16x16xf32>, tensor<16x16xf32>) -> tensor<16x16xf32>

    // Step 6: Element-wise sum: output = leaky_relu + leaky_relu
    %output = "stablehlo.add"(%leaky_relu, %leaky_relu) : (tensor<16x16xf32>, tensor<16x16xf32>) -> tensor<16x16xf32>

    // Return the output
    "stablehlo.return"(%output) : (tensor<16x16xf32>) -> ()
  }
}

// StableHLO program implementing a model that applies ELU activation
// to input tensor of shape 6x7, with alpha=1.0 (default).
// The program computes: output = F.elu(input, alpha=1.0)

func.func @main(%arg0: tensor<6x7xf32>) -> tensor<6x7xf32> {
  // Step 1: Define constant for alpha = 1.0
  %alpha = "stablehlo.constant"() {value = dense<1.0> : tensor<f32>} : () -> tensor<f32>

  // Step 2: Compute ELU activation
  // ELU(x) = max(0, x) + min(0, alpha * (exp(x) - 1))
  // First, compute exp(x)
  %exp_x = "stablehlo.exponential"(%arg0) : (tensor<6x7xf32>) -> tensor<6x7xf32>
  // Compute exp(x) - 1
  %exp_x_minus_one = "stablehlo.subtract"(%exp_x, %c_one) : (tensor<6x7xf32>, tensor<6x7xf32>) -> tensor<6x7xf32>
  // But need to define constant 1.0 as tensor
  %c_one = "stablehlo.constant"() {value = dense<1.0> : tensor<f32>} : () -> tensor<f32>
  // Wait, we already have %alpha as constant 1.0, but for clarity, define constant 1.0 again for subtraction
  // Alternatively, reuse %alpha for 1.0
  // So, for subtraction, use %c_one
  // Reuse %c_one
  // Compute exp(x) - 1
  %exp_x_minus_one = "stablehlo.subtract"(%exp_x, %c_one) : (tensor<6x7xf32>, tensor<6x7xf32>) -> tensor<6x7xf32>
  // Compute alpha * (exp(x) - 1)
  %alpha_times = "stablehlo.multiply"(%alpha, %exp_x_minus_one) : (tensor<f32>, tensor<6x7xf32>) -> tensor<6x7xf32>
  // Compute max(0, x)
  %zero = "stablehlo.constant"() {value = dense<0.0> : tensor<f32>} : () -> tensor<f32>
  %max_zero_x = "stablehlo.maximum"(%zero, %arg0) : (tensor<f32>, tensor<f32>) -> tensor<f32>
  // Compute min(0, alpha * (exp(x) - 1))
  %min_zero_alpha_expr = "stablehlo.minimum"(%zero, %alpha_times) : (tensor<f32>, tensor<f32>) -> tensor<f32>
  // Final ELU output: max(0, x) + min(0, alpha*(exp(x)-1))
  %output = "stablehlo.add"(%max_zero_x, %min_zero_alpha_expr) : (tensor<f32>, tensor<f32>) -> tensor<f32>
  // Return output
  return %output : tensor<6x7xf32>
}

