    broadcast_dimensions = array<i64: 1>
  } : (tensor<7xf32>) -> tensor<6x7xf32>

  // Step 3: Add bias to matmul result
  %add_bias = "stablehlo.add"(%matmul, %bias_broadcast) : (tensor<6x7xf32>, tensor<6x7xf32>) -> tensor<6x7xf32>

  // Step 4: Clone the result for residual addition
  // Since clone/detach is not explicitly modeled, we can simulate by just reusing the tensor
  // For the purpose of this program, treat %original_x as %add_bias
  %original_x = %add_bias

