// StableHLO program implementing the described PyTorch model forward pass
// with parameters passed as arguments, following the specified signature.

func.func @main(%arg0: tensor<16x1x1x1xf32>,        // scaling_factor
               %arg1: tensor<16x1x1x1xf32>,        // bias
               %arg2: tensor<16x3x3x3xf32>,        // conv.weight
               %arg3: tensor<16xf32>,              // conv.bias
               %arg4: tensor<6x3x16x7x7xf32>) -> tensor<6x16x14x5x5xf32> {
  // Step 1: Convolution
  %conv_result = "stablehlo.convolution"(%arg4, %arg2)
    {
      window_strides = dense<[1, 1, 1]> : tensor<3xi64>,
      padding = dense<[[1, 1], [1, 1], [1, 1]]] : tensor<3x2xi64>,
      lhs_dilation = dense<[1, 1, 1]> : tensor<3xi64>,
      rhs_dilation = dense<[1, 1, 1]> : tensor<3xi64>,
      dimension_numbers = #stablehlo.conv<[b, f, 0, 0, 0]x[o, i, 0, 0, 0]->[b, f, 0, 0, 0]>,
      feature_group_count = 1 : i64,
      batch_group_count = 1 : i64
    } : tensor<6x16x14x5x5xf32>

  // Step 2: Multiply convolution output by scaling_factor
  // broadcasting %arg0 (scaling_factor) over the remaining dims
  %broadcast_sf = "stablehlo.broadcast_in_dim"(%arg0)
    {
      broadcast_dimensions = array<i64: 0>,
    } : (tensor<16x1x1x1xf32>) -> tensor<6x16x14x5x5xf32>
  // To match shape, broadcast over batch and spatial dims
  %sf_broadcasted = "stablehlo.broadcast_in_dim"(%arg0)
    {
      broadcast_dimensions = array<i64: 0>,
    } : (tensor<16x1x1x1xf32>) -> tensor<6x16x14x5x5xf32>
  // But since shapes differ, better to broadcast %arg0 over batch and spatial dims
  // Use broadcast_in_dim with appropriate dims
  %sf_broadcast = "stablehlo.broadcast_in_dim"(%arg0)
    {
      broadcast_dimensions = array<i64: 0>,
    } : (tensor<16x1x1x1xf32>) -> tensor<6x16x14x5x5xf32>
  // For simplicity, broadcast %arg0 over batch and spatial dims
  // broadcast_dimensions: [0, 1, 2, 3, 4]
  // But %arg0 shape: 16x1x1x1, target shape: 6x16x14x5x5
  // So broadcast over dims 1,2,3,4
  %sf_broadcast_full = "stablehlo.broadcast_in_dim"(%arg0)
    {
      broadcast_dimensions = dense<[0, 1, 2, 3, 4]> : tensor<5xi64>,
    } : (tensor<16x1x1x1xf32>) -> tensor<6x16x14x5x5xf32>

  // Multiply convolution output by broadcasted scaling factor
  %scaled = "stablehlo.multiply"(%conv_result, %sf_broadcast_full)
    : (tensor<6x16x14x5x5xf32>, tensor<6x16x14x5x5xf32>) -> tensor<6x16x14x5x5xf32>

  // Step 3: Apply tanh
  %tanh = "stablehlo.tanh"(%scaled) : tensor<6x16x14x5x5xf32>

  // Step 4: Multiply by bias
  // Broadcast bias (%arg1) over batch and spatial dims
  %bias_broadcast = "stablehlo.broadcast_in_dim"(%arg1)
    {
      broadcast_dimensions = dense<[0, 1, 2, 3]> : tensor<4xi64>,
    } : (tensor<16x1x1x1xf32>) -> tensor<6x16x14x5x5xf32>
  %mult_bias = "stablehlo.multiply"(%tanh, %bias_broadcast)
    : (tensor<6x16x14x5x5xf32>, tensor<6x16x14x5x5xf32>) -> tensor<6x16x14x5x5xf32>

  // Step 5: Apply sigmoid
  %neg = "stablehlo.negate"(%mult_bias) : tensor<6x16x14x5x5xf32>
  %exp_neg = "stablehlo.exponential"(%neg) : tensor<6x16x14x5x5xf32>
  %one = "stablehlo.constant"() {value = dense<1.0> : tensor<f32>} : () -> tensor<f32>
  %denominator = "stablehlo.add"(%one, %exp_neg) : tensor<6x16x14x5x5xf32>
  %sigmoid = "stablehlo.divide"(%one, %denominator) : (tensor<f32>, tensor<6x16x14x5x5xf32>) -> tensor<6x16x14x5x5xf32>

  // Return the result
  return %sigmoid : tensor<6x16x14x5x5xf32>
}

// StableHLO program implementing the described PyTorch model in MLIR dialect
module {
  func.func @main(%arg0: tensor<7x6x4x4xf32>, %arg1: tensor<6xf32>, %arg2: tensor<6x7x7x7xf32>) -> tensor<6x6x16x16xf32> {
    // Step 1: Perform transposed convolution
    // Using the provided weight (%arg0) and bias (%arg1)
    %conv = "stablehlo.convolution"(%arg2, %arg0) {
      window_strides = dense<[2, 2]> : tensor<2xi64>,
      padding = dense<[[1, 2], [1, 2]]> : tensor<2x2xi64>,
      lhs_dilation = dense<[1, 1]> : tensor<2xi64>,
      rhs_dilation = dense<[1, 1]> : tensor<2xi64>,
      dimension_numbers = #stablehlo.conv<[b, f, 0, 1]x[o, i, 0, 1]->[b, f, 0, 1]>,
      feature_group_count = 1 : i64,
      batch_group_count = 1 : i64
    } : tensor<6x6x16x16xf32>;

    // Step 2: Add the bias (%arg1) to the convolution output
    // Broadcast bias to match shape
    // bias shape: [6], output shape: [6, 6, 16, 16]
    %bias_broadcast = "stablehlo.broadcast_in_dim"(%arg1) {
      broadcast_dimensions = array<i64: 0>
    } : (tensor<6xf32>) -> tensor<6x1x1x1xf32>;

    // Reshape bias to match output shape for broadcasting
    %bias_reshaped = "stablehlo.reshape"(%bias_broadcast) {
      shape = tensor<6x1x1x1xf32>
    } : tensor<6x1x1x1xf32>;

    // Broadcast bias to output shape
    %bias_broadcasted = "stablehlo.broadcast_in_dim"(%bias_reshaped) {
      broadcast_dimensions = array<i64: 0, 1, 2, 3>
    } : (tensor<6x1x1x1xf32>) -> tensor<6x6x16x16xf32>;

    // Add bias
    %add_bias = "stablehlo.add"(%conv, %bias_broadcasted) : tensor<6x6x16x16xf32>;

    // Step 3: Take element-wise minimum with zero (clamp to negative side)
    // Create constant zero tensor of shape [6,6,16,16]
    %zero_const = "stablehlo.constant"() {value = dense<0.0> : tensor<f32>} : () -> tensor<f32>;
    %zero_tensor = "stablehlo.broadcast_in_dim"(%zero_const) {
      broadcast_dimensions = array<i64: 0, 1, 2, 3>
    } : (tensor<f32>) -> tensor<6x6x16x16xf32>;

    %min_with_zero = "stablehlo.minimum"(%add_bias, %zero_tensor) : tensor<6x6x16x16xf32>;

    // Step 4: Apply GELU activation
    // GELU(x) = 0.5 * x * (1 + erf(x / sqrt(2)))
    // Compute x / sqrt(2)
    %sqrt2_const = "stablehlo.constant"() {value = dense<1.4142135623730951> : tensor<f32>} : () -> tensor<f32>;
    %inv_sqrt2 = "stablehlo.constant"() {value = dense<0.7071067811865475> : tensor<f32>} : () -> tensor<f32>;

    // Divide min_with_zero by sqrt(2)
    %x_div_sqrt2 = "stablehlo.divide"(%min_with_zero, %sqrt2_const) : tensor<6x6x16x16xf32>;

    // Compute erf(x / sqrt(2))
    %erf_x = "chlo.erf"(%x_div_sqrt2) : tensor<6x6x16x16xf32>;

    // Compute 1 + erf(...)
    %one_const = "stablehlo.constant"() {value = dense<1.0> : tensor<f32>} : () -> tensor<f32>;
    %one_plus_erf = "stablehlo.add"(%one_const, %erf_x) : tensor<6x6x16x16xf32>;

    // Multiply by x
    %x_times = "stablehlo.multiply"(%min_with_zero, %one_plus_erf) : tensor<6x6x16x16xf32>;

    // Multiply by 0.5
    %half_const = "stablehlo.constant"() {value = dense<0.5> : tensor<f32>} : () -> tensor<f32>;
    %gelu = "stablehlo.multiply"(%x_times, %half_const) : tensor<6x6x16x16xf32>;

    // Step 5: Multiply by multiply_value (constant 2.0)
    %mul_const = "stablehlo.constant"() {value = dense<2.0> : tensor<f32>} : () -> tensor<f32>;
    %result = "stablehlo.multiply"(%gelu, %mul_const) : tensor<6x6x16x16xf32>;

    // Return the final tensor
    return %result : tensor<6x6x16x16xf32>
  }
}

