func.func @main(%x: tensor<2x3xf32>) -> tensor<5x7xf32> {
  %c_neg_one = "stablehlo.constant"() {value = dense<-1.0> : tensor<f32>} : () -> tensor<f32>
  // Define padding for height dimension: 1 above, 2 below
  %padding_height = "stablehlo.constant"() {value = dense<[[1, 2]]]> : () -> tensor<1x2i64>
  // Define padding for width dimension: 2 left, 2 right
  %padding_width = "stablehlo.constant"() {value = dense<[[2, 2]]]> : () -> tensor<1x2i64>
  // Pad height dimension
  %padded_height = "stablehlo.pad"(%x, %c_neg_one) {
