      dot_dimension_numbers = #stablehlo.dot<lhs_batching_dimensions = [], rhs_batching_dimensions = [], lhs_contracting_dimensions = [1], rhs_contracting_dimensions = [1]>
    } : (tensor<16x16xf32>, tensor<16x16xf32>) -> tensor<16x16xf32>

    // Step 2: Apply GroupNorm
    // %arg2: weight tensor of shape [16]
    // %arg3: bias tensor of shape [16]
    // GroupNorm: normalize %gemm along features, then scale and shift
    // For simplicity, implement layer normalization as per batch statistics (since in training mode)
    // Compute mean over last dimension
    // mean = reduce_mean(%gemm, axes=[1])
    %axes1 = "stablehlo.constant"() {value = dense<[1]> : tensor<1> } : () -> tensor<1>
    %mean = "stablehlo.reduce"(%gemm, %arg2) {
      axes = %axes1
    } : (tensor<16x16xf32>, tensor<16>) -> tensor<16xf32>
    // Compute variance
    // diff = %gemm - broadcast_in_dim(%mean, shape of %gemm)
    %mean_bcast = "stablehlo.broadcast_in_dim"(%mean) {
      broadcast_dimensions = dense<[0]> : tensor<1>
    } : (tensor<16xf32>) -> tensor<16x16xf32>
    %diff = "stablehlo.subtract"(%gemm, %mean_bcast) : (tensor<16x16xf32>, tensor<16x16xf32>) -> tensor<16x16xf32>
    // Square diff
    %diff_sq = "stablehlo.multiply"(%diff, %diff) : (tensor<16x16xf32>, tensor<16x16xf32>) -> tensor<16x16xf32>
    // variance = reduce_mean of diff_sq over last dimension
    %var = "stablehlo.reduce"(%diff_sq, %arg2) {
      axes = %axes1
    } : (tensor<16x16xf32>, tensor<16>) -> tensor<16xf32>
    // Compute stddev = sqrt(variance + epsilon)
    // epsilon: small constant, e.g., 1e-5
    %epsilon = "stablehlo.constant"() {value = dense<1e-5 : f32>} : () -> tensor<f32>
    %var_plus_epsilon = "stablehlo.add"(%var, %epsilon) : (tensor<16xf32>, tensor<f32>) -> tensor<16xf32>
    %stddev = "stablehlo.sqrt"(%var_plus_epsilon) : (tensor<16xf32>) -> tensor<16xf32>
    // Normalize: (x - mean) / stddev
    // broadcast mean and stddev to shape [16,16]
    %mean_bcast2 = "stablehlo.broadcast_in_dim"(%mean) {
      broadcast_dimensions = dense<[1]> : tensor<1>
    } : (tensor<16xf32>) -> tensor<16x16xf32>
    %stddev_bcast = "stablehlo.broadcast_in_dim"(%stddev) {
      broadcast_dimensions = dense<[1]> : tensor<1>
    } : (tensor<16xf32>) -> tensor<16x16xf32>
    %x_centered = "stablehlo.subtract"(%gemm, %mean_bcast2) : (tensor<16x16xf32>, tensor<16x16xf32>) -> tensor<16x16xf32>
    %x_norm = "stablehlo.divide"(%x_centered, %stddev_bcast) : (tensor<16x16xf32>, tensor<16x16xf32>) -> tensor<16x16xf32>
    // Scale and shift: %x_norm * %arg2 + %arg3
    // broadcast %arg2 and %arg3 to shape [16,16]
    %scale_bcast = "stablehlo.broadcast_in_dim"(%arg2) {
      broadcast_dimensions = dense<[1]> : tensor<1>
    } : (tensor<16xf32>) -> tensor<16x16xf32>
    %shift_bcast = "stablehlo.broadcast_in_dim"(%arg3) {
      broadcast_dimensions = dense<[1]> : tensor<1>
    } : (tensor<16xf32>) -> tensor<16x16xf32>
    %scaled = "stablehlo.multiply"(%x_norm, %scale_bcast) : (tensor<16x16xf32>, tensor<16x16xf32>) -> tensor<16x16xf32>
    %gn_output = "stablehlo.add"(%scaled, %shift_bcast) : (tensor<16x16xf32>, tensor<16x16xf32>) -> tensor<16x16xf32>

    // Step 3: Apply HardTanh activation
    // min_val = -2.0, max_val = 2.0
    %min_const = "stablehlo.constant"() {value = dense<-2.0 : f32>} : () -> tensor<f32>
    %max_const = "stablehlo.constant"() {value = dense<2.0 : f32>} : () -> tensor<f32>
    // clip between min and max
    %clipped1 = "stablehlo.maximum"(%gn_output, %min_const) : (tensor<16x16xf32>, tensor<f32>) -> tensor<16x16xf32>
    %clipped2 = "stablehlo.minimum"(%clipped1, %max_const) : (tensor<16x16xf32>, tensor<f32>) -> tensor<16x16xf32>

    // Return the result
    return %clipped2 : tensor<16x16xf32>
  }
}

// StableHLO program to compute the forward pass of the described model
// with inputs: predictions and targets, both tensors<6x6xf32>
// Output: scalar f32 (the computed loss)

// Function signature
func.func @main(%arg0: tensor<6x6xf32>, %arg1: tensor<6x6xf32>) -> tensor<f32> {
  // Step 1: Compute element-wise difference: diff = predictions - targets
  %diff = "stablehlo.subtract"(%arg0, %arg1) : (tensor<6x6xf32>, tensor<6x6xf32>) -> tensor<6x6xf32>

  // Step 2: Compute absolute value of diff: abs_diff = abs(diff)
  %abs_diff = "stablehlo.abs"(%diff) : (tensor<6x6xf32>) -> tensor<6x6xf32>

  // Step 3: Compute element-wise square of abs_diff: sq = abs_diff * abs_diff
  %sq = "stablehlo.multiply"(%abs_diff, %abs_diff) : (tensor<6x6xf32>, tensor<6x6xf32>) -> tensor<6x6xf32>

  // Step 4: Compute mean of sq over all elements
  // First, reduce sum over all elements
  // Initialize scalar 0.0
  %zero = "stablehlo.constant"() {value = dense<0.0> : tensor<f32>} : () -> tensor<f32>
  // Reduce sum over all dims (0 and 1)
  %sum_all = "stablehlo.reduce"(%sq, %zero) ({
    ^bb0(%a: tensor<f32>, %b: tensor<f32>):
      %s = "stablehlo.add"(%a, %b) : (tensor<f32>, tensor<f32>) -> tensor<f32>
      "stablehlo.return"(%s) : (tensor<f32>) -> ()
  }) : (tensor<6x6xf32>, tensor<f32>) -> tensor<f32> (reducing over dims 0 and 1)
  // Now, divide by total number of elements (36) to get mean
  %div_const = "stablehlo.constant"() {value = dense<36.0> : tensor<f32>} : () -> tensor<f32>
  %mean_sq = "stablehlo.divide"(%sum_all, %div_const) : (tensor<f32>, tensor<f32>) -> tensor<f32>

  // Output the scalar loss
  // The result is tensor<f32> scalar
  return %mean_sq : tensor<f32>
}

