// StableHLO program to normalize each row of a tensor to unit L2 norm
func.func @main(%x: tensor<3x8xf32>) -> tensor<3x8xf32> {
  // Step 1: Compute x^2 element-wise
  %x_squared = "stablehlo.multiply" %x, %x : tensor<3x8xf32>

  // Step 2: Reduce along the last dimension (k) to get sum of squares per row
  %init_sum = "stablehlo.constant"() {value = dense<0.0 : f32>} : () -> tensor<8xf32>
  %sum_squares = "stablehlo.reduce" %x_squared, %init_sum ({
    ^bb0(%a: tensor<f32>, %b: tensor<f32>):
      %s = "stablehlo.add" %a, %b : tensor<f32>
      "stablehlo.return" %s : (tensor<f32>) -> ()
  }) {dimensions = array<i64: 1>} : (tensor<3x8xf32>, tensor<f32>) -> tensor<3xf32>

  // Step 3: Compute sqrt of sum of squares to get L2 norm per row
  %l2_norm = "stablehlo.sqrt" %sum_squares : tensor<3xf32>

  // Step 4: Broadcast l2_norm to shape (3x8) for division
  %broadcast_dims = "stablehlo.constant"() {value = dense<array<i64: 1>>} : () -> tensor<1x1xi64>
  %l2_norm_broadcast = "stablehlo.broadcast_in_dim" %l2_norm {broadcast_dimensions = array<i64: 1>} : tensor<3xf32> -> tensor<3x8xf32>

  // Step 5: Divide original x by broadcasted l2_norm
  %out = "stablehlo.divide" %x, %l2_norm_broadcast : tensor<3x8xf32>, tensor<3x8xf32>

  // Return the normalized tensor
  "stablehlo.return" %out : tensor<3x8xf32>
}

