  %x_bcast = "stablehlo.broadcast_in_dim"(%x) {
    broadcast_dimensions = array<i64: 0, 0, 1>
  } : (tensor<2x5xf32>) -> tensor<2x3x5xf32>

  // Broadcast %y to shape [2,3,5]
  %y_bcast = "stablehlo.broadcast_in_dim"(%y) {
    broadcast_dimensions = array<i64: 1, 0, 1>
  } : (tensor<3x5xf32>) -> tensor<2x3x5xf32>

  // Compute difference: diff = x_bcast - y_bcast
  %diff = "stablehlo.subtract"(%x_bcast, %y_bcast) : tensor<2x3x5xf32>

  // Compute squared difference: diff_sq = diff * diff
  %diff_sq = "stablehlo.multiply"(%diff, %diff) : tensor<2x3x5xf32>

  // Initialize reduction: sum over last dimension (dimension 2)
  // Create a constant zero tensor for initial value
  %zero = "stablehlo.constant"() {value = dense<0.0> : tensor<f32>} : () -> tensor<f32>

  // Reduce over dimension 2 to sum squared differences
  %squared_distances = "stablehlo.reduce"(%diff_sq, %zero) {
    ^bb0(%a: tensor<f32>, %b: tensor<f32>) : (tensor<f32>, tensor<f32>) {
      %sum = "stablehlo.add"(%a, %b) : (tensor<f32>, tensor<f32>) -> tensor<f32>
      "stablehlo.return"(%sum) : (tensor<f32>) -> ()
    }
  } : (tensor<2x3x5xf32>, tensor<f32>) -> tensor<2x3xf32> {
    dimensions = array<i64: 2>
  }

  // Return the result
  return %squared_distances : tensor<2x3xf32>
}

