// with convolution, subtraction, and Mish activation, in the specified signature.

func.func @main(%arg0: tensor<7x8x3x3xf32>, %arg1: tensor<7xf32>, %arg2: tensor<6x8x8x8xf32>) -> tensor<6x7x6x6xf32> {
  // Step 1: Perform convolution: %conv_out = conv(%arg2, %arg0)
  %window_strides = dense<[1, 1]> : tensor<2xi64>
  %padding = dense<[[1, 1], [1, 1]]> : tensor<2x2xi64>
  %lhs_dilation = dense<[1, 1]> : tensor<2xi64>
  %rhs_dilation = dense<[1, 1]> : tensor<2xi64>
  %dimension_numbers = #stablehlo.conv<[b, f, 0, 1]x[o, i, 0, 1]->[b, f, 0, 1]>
  %feature_group_count = 1 : i64
  %batch_group_count = 1 : i64

  %conv_out = "stablehlo.convolution"(%arg2, %arg0) {
    window_strides = %window_strides,
    padding = %padding,
    lhs_dilation = %lhs_dilation,
    rhs_dilation = %rhs_dilation,
    dimension_numbers = %dimension_numbers,
    feature_group_count = %feature_group_count,
    batch_group_count = %batch_group_count
  } : (tensor<6x8x8x8xf32>, tensor<7x8x3x3xf32>) -> tensor<6x7x6x6xf32>

  // Step 2: Subtract %arg1 (bias) from convolution output
  // Broadcast %arg1 (shape: 7) to match %conv_out shape: [6,7,6,6]
  %broadcast_dims = dense<[1, 0, 2, 3]> : tensor<4xi64>
  %bias_broadcasted = "stablehlo.broadcast_in_dim"(%arg1) {
    broadcast_dimensions = %broadcast_dims
  } : (tensor<7xf32>) -> tensor<6x7x6x6xf32>

  %subtracted = "stablehlo.subtract"(%conv_out, %bias_broadcasted) : (tensor<6x7x6x6xf32>, tensor<6x7x6x6xf32>) -> tensor<6x7x6x6xf32>

  // Step 3: Apply Mish activation: mish(x) = x * tanh(softplus(x))
  // Compute softplus(x) = log(1 + exp(x))
  %one = "stablehlo.constant"() {value = dense<1.0> : tensor<f32>} : () -> tensor<f32>
  %exp_x = "stablehlo.exponential"(%subtracted) : (tensor<6x7x6x6xf32>) -> tensor<6x7x6x6xf32>
  %add_exp = "stablehlo.add"(%exp_x, %one) : (tensor<6x7x6x6xf32>, tensor<1x1x1x1xf32>) -> tensor<6x7x6x6xf32>
  %softplus = "stablehlo.log"(%add_exp) : (tensor<6x7x6x6xf32>) -> tensor<6x7x6x6xf32>

  // Compute tanh(softplus(x))
  %tanh_softplus = "stablehlo.tanh"(%softplus) : (tensor<6x7x6x6xf32>) -> tensor<6x7x6x6xf32>

  // Compute x * tanh(softplus(x))
  %mish = "stablehlo.multiply"(%subtracted, %tanh_softplus) : (tensor<6x7x6x6xf32>, tensor<6x7x6x6xf32>) -> tensor<6x7x6x6xf32>

  // Return the result
  return %mish : tensor<6x7x6x6xf32>
}

