// with parameters passed as arguments, following the specified signature.

func.func @main(%arg0: tensor<16xf32>,        // bias
               %arg1: tensor<16x16xf32>,    // gemm.weight
               %arg2: tensor<16xf32>,       // gemm.bias
               %arg3: tensor<16xf32>,       // groupnorm.weight
               %arg4: tensor<16xf32>,       // groupnorm.bias
               %arg5: tensor<16x16xf32>) -> tensor<16x16xf32> {
