  } : (tensor<16x16xf32>, tensor<16x16xf32>) -> tensor<16x16xf32>

  // Step 2: Add bias: %add_bias = "stablehlo.add"(%matmul, %arg2)
  %add_bias = "stablehlo.add"(%matmul, %arg2) : tensor<16x16xf32>

  // Step 3: Hardtanh activation
  // Hardtanh clamps between -1.0 and 1.0
  // Use "stablehlo.maximum" and "stablehlo.minimum" to implement clamp
  %minus_one = "stablehlo.constant"() {value = dense<-1.0> : tensor<f32>} : () -> tensor<f32>
  %one = "stablehlo.constant"() {value = dense<1.0> : tensor<f32>} : () -> tensor<f32>
  %clamped_min = "stablehlo.maximum"(%add_bias, %minus_one) : tensor<16x16xf32>
  %clamped = "stablehlo.minimum"(%clamped_min, %one) : tensor<16x16xf32>

  // Step 4: Mish activation: x * tanh(softplus(x))
  // softplus(x) = log(1 + exp(x))
