  // To get mean, divide sum by 16
  %16 = "stablehlo.constant"() {value = dense<16> : tensor<i64>} : () -> tensor<i64>
  %mean_div = "stablehlo.convert"(%mean) : (tensor<16xf32>) -> tensor<16xf32>
