    broadcast_dimensions = array<i64: 1>
  } : (tensor<16xf32>) -> tensor<16x16xf32>
  %diff = "stablehlo.subtract"(%mish, %broadcast_mean) : tensor<16x16xf32>
  %diff_sq = "stablehlo.multiply"(%diff, %diff) : tensor<16x16xf32>
  %var_sum = "stablehlo.reduce"(%diff_sq, %zero_f32) {
    ^bb0(%a: tensor<16x16xf32>, %b: tensor<f32>) -> (tensor<f32>) {
      %sum = "stablehlo.add"(%a, %b) : tensor<16x16xf32>
      "stablehlo.return"(%sum) : (tensor<f32>) -> ()
    }
  } {dimensions = array<i64: 1>} : (tensor<16x16xf32>, tensor<f32>) -> tensor<16xf32>
  %var_div = "stablehlo.convert"(%var_sum) : (tensor<16xf32>) -> tensor<16xf32>
  %variance = "stablehlo.divide"(%var_div, %16) : tensor<16xf32>

  // epsilon for numerical stability
  %epsilon = "stablehlo.constant"() {value = dense<1e-5> : tensor<f32>} : () -> tensor<f32>
  %var_plus_eps = "stablehlo.add"(%variance, %epsilon) : tensor<16xf32>
  %stddev = "stablehlo.sqrt"(%var_plus_eps) : tensor<16xf32>

  // Normalize: (x - mean) / stddev
