    // Step 3: Tanh
    %tanh = "stablehlo.tanh"(%norm2) : tensor<16x14x14xf32>

    // Step 4: HardSwish
    // HardSwish: x * relu6(x + 3) / 6
    // Implement relu6 as min(max(x+3, 0), 6)
    %three = "stablehlo.constant"() {value = dense<3.0> : tensor<f32>} : () -> tensor<f32>
    %six = "stablehlo.constant"() {value = dense<6.0> : tensor<f32>} : () -> tensor<f32>
    %x_plus_3 = "stablehlo.add"(%tanh, %three) : tensor<16x14x14xf32>
    %relu6_part = "stablehlo.maximum"(%x_plus_3, %c0) : tensor<16x14x14xf32> // %c0 is constant zero
    %relu6 = "stablehlo.minimum"(%relu6_part, %six) : tensor<16x14x14xf32>
    // HardSwish numerator: x * relu6(x+3)
    %hs_num = "stablehlo.multiply"(%tanh, %relu6) : tensor<16x14x14xf32>
    // Divide by 6
    %hs_div = "stablehlo.divide"(%hs_num, %six) : tensor<16x14x14xf32>

    // Step 5: Residual addition: conv + hard swish
    %residual = "stablehlo.add"(%conv, %hs_div) : tensor<16x14x14xf32>

    // Step 6: LogSumExp over dim=1 (channel dimension)
    // For LogSumExp, compute max over dim=1, then sum exp, then log
    // Compute max over dim=1
    %max_val = "stablehlo.reduce"(%residual, %c_neg_inf) {
      dimensions = dense<[1]> : tensor<1xi64>
    } : tensor<16x14x14xf32>
    // Subtract max for numerical stability
    %res_minus_max = "stablehlo.subtract"(%residual, "stablehlo.broadcast_in_dim"(%max_val) {
      broadcast_dimensions = array<i64: 1>
    }) : tensor<16x14x14xf32>
    // Exponentiate
    %exp_res = "stablehlo.exponential"(%res_minus_max) : tensor<16x14x14xf32>
    // Sum over dim=1
    %sum_exp = "stablehlo.reduce"(%exp_res, %c0) {
      dimensions = dense<[1]> : tensor<1xi64>
    } : tensor<16x14x14xf32>
    // Take log
    %log_sum_exp = "stablehlo.log"(%sum_exp) : tensor<16x14x14xf32>
    // Add max back
    %logsumexp = "stablehlo.add"(%log_sum_exp, "stablehlo.broadcast_in_dim"(%max_val) {
      broadcast_dimensions = array<i64: 1>
    }) : tensor<16x14x14xf32>

    // Final output shape: [16,1,14,14]
    // Expand dims at axis=1
    %output = "stablehlo.reshape"(%logsumexp) : (tensor<16x14x14xf32>) -> tensor<16x1x14x14xf32>

    return %output : tensor<16x1x14x14xf32>
  }

  // Constants
  %c0 = "stablehlo.constant"() {value = dense<0.0> : tensor<f32>} : () -> tensor<f32>
  %c_neg_inf = "stablehlo.constant"() {value = dense<-1e20> : tensor<f32>} : () -> tensor<f32>
}

