    padding = %padding,
    lhs_dilation = %lhs_dilation,
    rhs_dilation = %rhs_dilation,
    dimension_numbers = #stablehlo.conv<[b, f, h, w] x [o, i, kh, kw] -> [b, f, h_out, w_out]>,
    feature_group_count = %feature_group_count,
    batch_group_count = %batch_group_count
  } : (tensor<8x6x7x7xf32>, tensor<3x7x7x6>) -> tensor<8x6x9x13xf32>

