func.func @main(%arg0: tensor<1x16x1x1xf32>,   // bias
               %arg1: tensor<16x16xf32>,      // gemm.weight
               %arg2: tensor<16xf32>,         // gemm.bias
               %arg3: tensor<16xf32>,         // group_norm.weight
               %arg4: tensor<16xf32>,         // group_norm.bias
               %arg5: tensor<16x16xf32>) -> tensor<1x16x16x1xf32> { // input0

  // Step 1: GEMM (matrix multiplication + bias addition)
  // GEMM: %gemm_out = matmul(%arg1, %arg5) + %arg2
  // Since matmul is dot_general with batching dims empty, contracting dims [1] and [1]
  %zero_dim = constant dense<0> : tensor<i64>
  %one_dim = constant dense<1> : tensor<i64>
  // Dot general for matrix multiplication
  %gemm = "stablehlo.dot_general"(%arg1, %arg5) {
    dot_dimension_numbers = #stablehlo.dot<lhs_contracting_dimensions = [1], rhs_contracting_dimensions = [1], lhs_batching_dimensions = [] , rhs_batching_dimensions = []>
  } : (tensor<16x16xf32>, tensor<16x16xf32>) -> tensor<16x16xf32>
  // Add bias: broadcast bias to shape of gemm output
  // bias shape: (16), need to broadcast to (16x16)
  %bias_broadcast = "stablehlo.broadcast_in_dim"(%arg2) {
    broadcast_dimensions = array<i64: 1>
  } : (tensor<16xf32>) -> tensor<16x16xf32>
  %gemm_bias = "stablehlo.broadcast_in_dim"(%arg2) {
    broadcast_dimensions = array<i64: 1>
