  // group_norm: normalize across features, then scale and shift
  // Compute mean and variance across feature dimension (dim=1)
  // For simplicity, approximate layer norm as per batch norm in training mode
  // Compute mean
  %reduction_axes = array<i64: 1>
  %mean = "stablehlo.reduce"(%gemm_out, %zero) {
    axes = %reduction_axes
  } : (tensor<16x16xf32>, tensor<f32>) -> tensor<16x1xf32>
  // Expand mean to shape of gemm_out
  %mean_broadcast = "stablehlo.broadcast_in_dim"(%mean) {
    broadcast_dimensions = array<i64: 1>
  } : (tensor<16x1xf32>) -> tensor<16x16xf32>
  // Compute squared difference
  %diff = "stablehlo.subtract"(%gemm_out, %mean_broadcast) : (tensor<16x16xf32>, tensor<16x16xf32>) -> tensor<16x16xf32>
  %diff_sq = "stablehlo.multiply"(%diff, %diff) : (tensor<16x16xf32>, tensor<16x16xf32>) -> tensor<16x16xf32>
  // Compute variance
  %var = "stablehlo.reduce"(%diff_sq, %zero) {
    axes = %reduction_axes
  } : (tensor<16x16xf32>, tensor<f32>) -> tensor<16x1xf32>
  // Compute stddev = sqrt(variance + epsilon)
  %epsilon = constant dense<1e-5 : f32> : tensor<f32>
  %var_plus_eps = "stablehlo.add"(%var, %epsilon) : (tensor<16x1xf32>, tensor<f32>) -> tensor<16x1xf32>
  %stddev = "stablehlo.sqrt"(%var_plus_eps) : (tensor<16x1xf32>) -> tensor<16x1xf32>
  // Broadcast stddev
  %stddev_broadcast = "stablehlo.broadcast_in_dim"(%stddev) {
    broadcast_dimensions = array<i64: 1>
  } : (tensor<16x1xf32>) -> tensor<16x16xf32>
  // Normalize
  %normalized = "stablehlo.divide"(%diff, %stddev_broadcast) : (tensor<16x16xf32>, tensor<16x16xf32>) -> tensor<16x16xf32>
  // Scale and shift: multiply by group_norm.weight and add group_norm.bias
  // Broadcast group_norm.weight
  %gn_weight_broadcast = "stablehlo.broadcast_in_dim"(%arg3) {
    broadcast_dimensions = array<i64: 1>
  } : (tensor<16xf32>) -> tensor<16x16xf32>
  %gn_bias_broadcast = "stablehlo.broadcast_in_dim"(%arg4) {
    broadcast_dimensions = array<i64: 1>
  } : (tensor<16xf32>) -> tensor<16x16xf32>
  // Scale
  %scaled = "stablehlo.multiply"(%normalized, %gn_weight_broadcast) : (tensor<16x16xf32>, tensor<16x16xf32>) -> tensor<16x16xf32>
  // Shift
  %norm_out = "stablehlo.add"(%scaled, %gn_bias_broadcast) : (tensor<16x16xf32>, tensor<16x16xf32>) -> tensor<16x16xf32>

  // Step 3: Compute minimum across feature dimension (dim=1), keepdim=True
  // For min, reduce over dim=1
  %min_axes = array<i64: 1>
  %min_value = "stablehlo.reduce"(%norm_out, %arg2) {
    axes = %min_axes
