  // Add bias (from argument 0) to min_value
  // bias shape: (1,16,1,1), need to broadcast to (1,16,1,1)
  // But min_broadcast shape is (16,16), need to reshape to (1,16,1,1)
  %bias_reshaped = "stablehlo.reshape"(%arg0) {
    shape = tensor<1x16x1x1xf32>
  } : (tensor<1x16x1x1xf32>) -> tensor<1x16x1x1xf32>
  // Broadcast min_broadcast to shape of bias
  // First, reshape min_broadcast to (1,16,1,1)
  %min_reshaped = "stablehlo.reshape"(%min_broadcast) {
    shape = tensor<1x16x1x1xf32>
  } : (tensor<16x1xf32>) -> tensor<1x16x1x1xf32>
