  %min_plus_bias = "stablehlo.add"(%min_reshaped, %arg0) : (tensor<1x16x1x1xf32>, tensor<1x16x1x1xf32>) -> tensor<1x16x1x1xf32>

  // Step 4: Add the result of min + bias to the normalized output
  // Broadcast min_plus_bias to shape of norm_out
  %min_broadcast_full = "stablehlo.broadcast_in_dim"(%min_plus_bias) {
    broadcast_dimensions = array<i64: 0, 1, 2, 3>
  } : (tensor<1x16x1x1xf32>) -> tensor<16x16xf32>
  // Since norm_out shape is (16,16), need to reshape min_plus_bias to (16,16)
  %min_broadcast_2 = "stablehlo.reshape"(%min_plus_bias) {
    shape = tensor<16x16xf32>
  } : (tensor<1x16x1x1xf32>) -> tensor<16x16xf32>
  // Add to normalized output
  %final_norm = "stablehlo.add"(%norm_out, %min_broadcast_2) : (tensor<16x16xf32>, tensor<16x16xf32>) -> tensor<16x16xf32>

  // Step 5: Final reshape to match output shape: (1,16,16,1)
  %reshaped_output = "stablehlo.reshape"(%final_norm) {
    shape = tensor<1x16x16x1xf32>
  } : (tensor<16x16xf32>) -> tensor<1x
